from docx import Document
from docx.shared import Cm, Pt, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

B=Path(__file__).parent
d=Document(B/'original.docx')
ps=list(d.paragraphs)
changes=[]
def replace(i,text):
    p=ps[i]; old=p.text
    if old==text:return
    changes.append({'paragraph':i,'before':old,'after':text})
    # Retain paragraph properties (lists, bookmarks, styles), replace text only.
    for child in list(p._p):
        if child.tag not in (qn('w:pPr'),qn('w:bookmarkStart'),qn('w:bookmarkEnd')):p._p.remove(child)
    p.add_run(text)
def delete(i):
    p=ps[i]
    changes.append({'paragraph':i,'before':p.text,'after':''})
    p._p.getparent().remove(p._p)

