# Use a single readable table style, retaining sizes and formula objects.
for ti,t in enumerate(d.tables):
    formula=ti in [6,12]
    for ri,row in enumerate(t.rows):
        pr=row._tr.get_or_add_trPr()
        if ri==0 and not formula:
            h=OxmlElement('w:tblHeader');pr.append(h)
        # Allow long narrative rows to split rather than overflow the page.
        for ns in list(pr.findall(qn('w:cantSplit'))):pr.remove(ns)
        for c in row.cells:
            for p in c.paragraphs:
                pf=p.paragraph_format;pf.first_line_indent=Cm(0);pf.line_spacing=1
                pf.space_before=Pt(2);pf.space_after=Pt(2);pf.keep_with_next=False
                pf.alignment=WD_ALIGN_PARAGRAPH.CENTER if formula or ri==0 else WD_ALIGN_PARAGRAPH.LEFT
                for r in p.runs:r.font.name='Times New Roman';r.font.size=Pt(12 if not formula else 14);r.font.color.rgb=RGBColor(0,0,0)
    # Table widths must fit inside 16.5 cm text area.
    maxw=Cm(16.5)
    if sum(c.width or 0 for c in t.columns)>maxw:
        total=sum(c.width or 0 for c in t.columns)
        for col in t.columns:col.width=int((col.width or 0)*maxw/total)

